    cbd marker: validate precision

diff --git a/.vscode/launch.json b/.vscode/launch.json
index 531768e..472c5f7 100644
--- a/.vscode/launch.json
+++ b/.vscode/launch.json
@@ -49,8 +49,9 @@
                 "-i",
                 "~/temp/input_01",
                 "-o",
-                "~/temp/input_01.tif",
-                "-v"
+                "~/temp/input_01.png",
+                "-v",
+                "-d 0,0,1024,1024"
             ],
             "stopAtEntry": true,
             "cwd": "${workspaceFolder}",
diff --git a/src/lib/core/codestream/CodeStreamDecompress_Markers.cpp b/src/lib/core/codestream/CodeStreamDecompress_Markers.cpp
index e5f592a..a5c382c 100644
--- a/src/lib/core/codestream/CodeStreamDecompress_Markers.cpp
+++ b/src/lib/core/codestream/CodeStreamDecompress_Markers.cpp
@@ -942,7 +942,15 @@ bool CodeStreamDecompress::read_cbd(uint8_t* headerData, uint16_t header_size)
          grk_read<uint8_t>(headerData++, &comp_def);
          auto comp = getHeaderImage()->comps + i;
          comp->sgnd = ((uint32_t)(comp_def >> 7U) & 1U);
-         comp->prec = (uint8_t)((comp_def & 0x7f) + 1U);
+         auto prec = (uint8_t)((comp_def & 0x7f) + 1U);
+         if(prec > GRK_MAX_SUPPORTED_IMAGE_PRECISION)
+         {
+                Logger::logger_.error("CBD marker: precision %d for component %d is greater than maximum "
+                                                          "supported precision %d",
+                                                          prec, i, GRK_MAX_SUPPORTED_IMAGE_PRECISION);
+                return false;
+         }
+         comp->prec = prec;
    }

    return true;
